import { Injectable, inject } from '@angular/core';
import { HttpClient }          from '@angular/common/http';
import { Observable }          from 'rxjs';
import { environment }         from '../../environments/environment';
import { AlertDto, HistoryItemDto } from '../models/audit.model';

@Injectable({ providedIn: 'root' })
export class AuditService {
  private readonly api  = inject(HttpClient);
  private readonly base = environment.apiUrl;

  getAlerts(branchId?: number): Observable<AlertDto[]> {
    const params: Record<string, string> = {};
    if (branchId !== undefined) params['branchId'] = branchId.toString();
    return this.api.get<AlertDto[]>(`${this.base}/audit/alerts`, { params });
  }

  getHistory(employeeId: number, date: string): Observable<HistoryItemDto[]> {
    return this.api.get<HistoryItemDto[]>(`${this.base}/audit/history`, {
      params: { employeeId: employeeId.toString(), date }
    });
  }
}
